def f(x):
    x += 1
    while x % 10 == 0:
        x //= 10
    return x

def solve(n):
    visited = set()
    queue = [n]

    while queue:
        curr = queue.pop(0)
        if curr in visited:
            continue
        visited.add(curr)

        next_val = f(curr)
        if next_val not in visited:
            queue.append(next_val)

    return len(visited)

