def solve():
    lines = []
    for _ in range(3):
        line = input().strip()
        lines.append(line)

    # Parse the three comparisons
    comparisons = []
    for line in lines:
        if '<' in line:
            left, right = line.split('<')
            comparisons.append((left, right, 'less'))
        elif '>' in line:
            left, right = line.split('>')
            comparisons.append((left, right, 'greater'))

    # We need to determine the order of A, B, C
    # We'll try to build a directed graph of relationships
    # Then check for cycles (which would mean contradiction)

    # Build adjacency list: from X to Y means X < Y
    graph = {c: [] for c in 'ABC'}

    for left, right, rel in comparisons:
        if rel == 'less':
            # left < right
            graph[left].append(right)
        else:  # rel == 'greater'
            # left > right, so right < left
            graph[right].append(left)

    # Check for cycles using DFS (topological sort)
    def has_cycle():
        visited = {c: 0 for c in 'ABC'}  # 0: unvisited, 1: visiting, 2: visited
        def dfs(node):
            if visited[node] == 1:
                return True
            if visited[node] == 2:
                return False

            visited[node] = 1
            for neighbor in graph[node]:
                if dfs(neighbor):
                    return True
            visited[node] = 2
            return False

        for node in 'ABC':
            if visited[node] == 0:
                if dfs(node):
                    return True
        return False

    if has_cycle():
        print("Impossible")
        return

    # Now we need to find the topological order (increasing order)
    # We'll do a topological sort using Kahn's algorithm

    # Count in-degrees
    in_degree = {c: 0 for c in 'ABC'}
    for node in 'ABC':
        for neighbor in graph[node]:
            in_degree[neighbor] += 1

    # Queue for nodes with in-degree 0
    queue = []
    for node in 'ABC':
        if in_degree[node] == 0:
            queue.append(node)

    # Topological sort
    result = []
    while queue:
        node = queue.pop(0)
        result.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If we didn't get all 3 nodes, there's a problem
    if len(result) != 3:
        print("Impossible")
        return

    # The result is in topological order (increasing order)
    # So we output the letters in order
    print(''.join(result))

