def solve():
    n = int(input())
    commands = input().strip()

    count = 0

    # Check all possible contiguous substrings
    for i in range(n):
        for j in range(i, n):
            # Extract substring from i to j (inclusive)
            substring = commands[i:j+1]

            # Calculate net movement
            dx, dy = 0, 0
            for cmd in substring:
                if cmd == 'R':
                    dx += 1
                elif cmd == 'L':
                    dx -= 1
                elif cmd == 'U':
                    dy += 1
                elif cmd == 'D':
                    dy -= 1

            # Return to start if net movement is (0,0)
            if dx == 0 and dy == 0:
                count += 1

    return count

print(solve())
